import com.praxicraft.assess.Client; import java.util.*;
public class Main { public static void main(String[] a) throws Exception { Client c=new Client(); Map m=c.assessments().create(Map.of("title","Example screen")); String slug=(String)m.get("slug"); System.out.println(slug); String id=System.getenv("PRAXICRAFT_TASK_ID"); if(id!=null&&!id.isBlank()) c.assessments().attachTasks(slug, Map.of("tasks", List.of(Map.of("task_id",id,"source","platform")))); } }
